public class Cookie {
    private String flavor;

    public Cookie(String flavor) {
        this.flavor = flavor;
    }

    public String getFlavor() {
        return flavor;
    }

    public String describe() {
        return "A " + flavor + " cookie.";
    }
}

public class DecoratedCookie extends Cookie {
    private String occasion;

    public DecoratedCookie(String occasion) {
        super("Sugar");
        this.occasion = occasion;
    }

    public String getOccasion() {
        return occasion;
    }

    @Override
    public String describe() {
        return "A " + getFlavor() + " cookie decorated for a " + occasion + ".";
    }
}
